   104	int EVP_EncodedLength(size_t *out_len, size_t len) {
   105	  if (len + 2 < len) {
   106	    return 0;
   107	  }
   108	  len += 2;
   109	  len /= 3;
   110	
   111	  if (((len << 2) >> 2) != len) {
   112	    return 0;
   113	  }
   114	  len <<= 2;
   115	
   116	  if (len + 1 < len) {
   117	    return 0;
   118	  }
   119	  len++;
   120	
   121	  *out_len = len;
   122	  return 1;
   123	}
