   384	int EVP_DecodeFinal(EVP_ENCODE_CTX *ctx, uint8_t *out, int *out_len) {
   385	  *out_len = 0;
   386	  if (ctx->error_encountered || ctx->data_used != 0) {
   387	    return -1;
   388	  }
   389	
   390	  return 1;
   391	}
